window.ScripturaLexicons.BDAG_PART_0270 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0270-01\" data-source=\"BDAG\" data-search=\"παράκλητος, ου, ὁ substantivo masculino intercessor; auxiliador; defensor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παράκλητος, ου, ὁ</td><td>substantivo masculino</td><td>intercessor; auxiliador; defensor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0270-02\" data-source=\"BDAG\" data-search=\"παρακοή, ῆς, ἡ substantivo feminino desobediência; recusa em ouvir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρακοή, ῆς, ἡ</td><td>substantivo feminino</td><td>desobediência; recusa em ouvir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0270-03\" data-source=\"BDAG\" data-search=\"παρακολουθέω verbo seguir; acompanhar atentamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρακολουθέω</td><td>verbo</td><td>seguir; acompanhar atentamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0270-04\" data-source=\"BDAG\" data-search=\"παρακούω verbo ouvir por acaso; ignorar; desobedecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρακούω</td><td>verbo</td><td>ouvir por acaso; ignorar; desobedecer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0270-05\" data-source=\"BDAG\" data-search=\"παρακύπτω verbo inclinar-se para olhar; perscrutar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρακύπτω</td><td>verbo</td><td>inclinar-se para olhar; perscrutar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0270-06\" data-source=\"BDAG\" data-search=\"παραλαμβάνω verbo tomar consigo; receber; aceitar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραλαμβάνω</td><td>verbo</td><td>tomar consigo; receber; aceitar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0270-07\" data-source=\"BDAG\" data-search=\"παραλέγομαι verbo médio depoente navegar ao longo da costa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραλέγομαι</td><td>verbo médio depoente</td><td>navegar ao longo da costa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0270-08\" data-source=\"BDAG\" data-search=\"παραλείπω verbo deixar de lado; omitir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραλείπω</td><td>verbo</td><td>deixar de lado; omitir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0270-09\" data-source=\"BDAG\" data-search=\"παραλημφθήσομαι remissão verbal ver παραλαμβάνω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραλημφθήσομαι</td><td>remissão verbal</td><td>ver παραλαμβάνω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0270-10\" data-source=\"BDAG\" data-search=\"παράλιος, ον adjetivo litorâneo; região costeira BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παράλιος, ον</td><td>adjetivo</td><td>litorâneo; região costeira</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0270-11\" data-source=\"BDAG\" data-search=\"παραλλαγή, ῆς, ἡ substantivo feminino mudança; variação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραλλαγή, ῆς, ἡ</td><td>substantivo feminino</td><td>mudança; variação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0270-12\" data-source=\"BDAG\" data-search=\"παραλλάσσω verbo mudar; diferir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραλλάσσω</td><td>verbo</td><td>mudar; diferir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0270-13\" data-source=\"BDAG\" data-search=\"παραλογίζομαι verbo médio depoente enganar; defraudar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραλογίζομαι</td><td>verbo médio depoente</td><td>enganar; defraudar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0270-14\" data-source=\"BDAG\" data-search=\"παραλόγως advérbio irracionalmente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραλόγως</td><td>advérbio</td><td>irracionalmente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0270-15\" data-source=\"BDAG\" data-search=\"παραλυτικός, ή, όν adjetivo substantivado paralítico; pessoa paralisada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραλυτικός, ή, όν</td><td>adjetivo substantivado</td><td>paralítico; pessoa paralisada</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0270-16\" data-source=\"BDAG\" data-search=\"παράλυτος, ον adjetivo substantivado paralítico BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παράλυτος, ον</td><td>adjetivo substantivado</td><td>paralítico</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0270-17\" data-source=\"BDAG\" data-search=\"παραλύω verbo enfraquecer; paralisar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραλύω</td><td>verbo</td><td>enfraquecer; paralisar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0270-18\" data-source=\"BDAG\" data-search=\"παραμένω verbo permanecer; continuar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραμένω</td><td>verbo</td><td>permanecer; continuar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0270-19\" data-source=\"BDAG\" data-search=\"παράμονος ον adjetivo duradouro; persistente; obstinado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παράμονος ον</td><td>adjetivo</td><td>duradouro; persistente; obstinado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0270-20\" data-source=\"BDAG\" data-search=\"παραμυθέομαι verbo médio depoente consolar; animar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραμυθέομαι</td><td>verbo médio depoente</td><td>consolar; animar</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0270-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παράκλητος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παράκλητος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">παρακαλέω</span>) significava originalmente em sentido passivo (BGU 601, 12 [II d.C.] <span class=\"greek\">παράκλητος</span> <span class=\"greek\">δέδωκα</span> <span class=\"greek\">αὐτῷ</span> = «quando me foi pedido, dei-lhe», mas <span class=\"greek\">π</span>. foi restituído a partir de <span class=\"greek\">παρακλος</span>, e a restituição é incerta) «aquele que é chamado em auxílio de alguém». Assim, escritores latinos habitualmente o traduziram, nas ocorrências do NT, por advocatus (Tertuliano, Prax. 9; Cipriano, De Domin. Orat. 3, Epist. 55, 18; Novaciano, De Trin. 28; 29; Hilário, De Trin. 8, 19; Lúcifer, De S. Athanas. 2, 26; Agostinho, C. Faust. 13, 17, Tract. in Joh. 94; Tractatus Orig. 20 p. 212, 13 Batiffol. Igualmente muitos manuscritos bíblicos [da Vetus Latina]: a c e m q <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:16</a>; a m q 14:26; e q r 15:26; e m q 16:7. Eus., HE 5, 1, 10 <span class=\"greek\">παράκλητος</span> = advocatus, Rufino. Field, Notes 102f; cf. o papel do patronus nos procedimentos jurídicos: J-MDavid, Le patronat judicaire au dernier siècle de la république romaine ’92). Contudo, o significado técnico «advogado», «procurador» é raro (p. ex., Bíon de Borístenes [III a.C.] em Diog. L. 4, 50; SEG XXXVIII, 1237, 18 [235/36 d.C.]). Contra a associação jurídica: KGrayston, JSNT 13, ’81, 67–82. Nos poucos lugares em que a palavra também se encontra na literatura pré-cristã e extracristã, possui predominantemente sentido mais geral: aquele que comparece em favor de outrem, mediador, intercessor, auxiliador (Demosth. 19, 1; Dionys. Hal. 11, 37, 1; Heraclit. Sto. 59 p. 80, 19; Cass. Dio 46, 20, 1; POxy 2725, 10 [71 d.C.]; cf. <span class=\"greek\">π</span>. como nome de um éon gnóstico Iren. 1, 4, 5 [Harv. I 38, 8]; Hippol.; veja também as observações sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:20</a> s.v. <span class=\"greek\">παρακαλέω</span> 2). A ideia passiva de <span class=\"greek\">παρακεκλῆσθαι</span> recuou para segundo plano, sendo substituída pela ideia ativa de <span class=\"greek\">παρακαλεῖν</span> (sobre a justificativa para equiparar <span class=\"greek\">παράκλητος</span> a <span class=\"greek\">παρακαλῶν</span>, veja Kühner-Bl. II 289). Os judeus o adotaram nesse sentido como empréstimo linguístico (<span class=\"hebrew\" dir=\"rtl\">פְּרַקְלֵיט</span>. Pirqe Aboth 4, 11.—SKrauss, Griech. u. latein. Lehnwörter in Talmud, Midrasch u. Targum 1898/99 I 210; II 496; Dalman, Gramm.2 185; Billerb. II 560–62). Em Job 16:2, Aq. e Theod. traduzem <span class=\"hebrew\" dir=\"rtl\">מְנַחֲמִים</span> (= «consoladores») por <span class=\"greek\">παράκλητοι</span>; a LXX tem <span class=\"greek\">παρακλήτορες</span>. Em Fílon, nossa palavra significa por vezes «intercessor» (De Jos. 239, Vi. Mos. 2, 134, Spec. Leg. 1, 237, Exsecr. 166, Adv. Flacc. 13; 22), por vezes «conselheiro», «auxiliador» (Op. M. 23; 165). Os intérpretes gregos do Evangelho de João entenderam-na no sentido ativo = <span class=\"greek\">παρακαλῶν</span> ou <span class=\"greek\">παρακλήτωρ</span> (veja Lampe s.v. <span class=\"greek\">παράκλητο</span>, especialmente Eusébio de Cesareia, Teodoro de Mopsuéstia e Amônio; veja também Efrém, o Sírio, em RHarris, Fragments of the Comm. of Ephrem Syr. 1895, 86). Em nossa literatura, o sentido ativo «auxiliador, intercessor» é adequado a todas as ocorrências da palavra (assim Goodsp, Probs. 110f). <span class=\"greek\">τίς</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">παράκλητος</span> <span class=\"greek\">ἔσται</span>; «Quem será nosso intercessor?» 2 Cl 6:9. <span class=\"greek\">πλουσίων</span> <span class=\"greek\">παράκλητοι</span> «defensores dos ricos» B 20:2; D 5:2.—Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:1</a> (assim como em AcJ, num fragmento danificado: POxy 850, 10), Cristo é designado <span class=\"greek\">παράκλητος</span>: <span class=\"greek\">παράκλητον</span> <span class=\"greek\">ἔχομεν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">πατέρα</span> <span class=\"greek\">Ἰησοῦν</span> <span class=\"greek\">Χριστὸν</span> <span class=\"greek\">δίκαιον</span> «temos Jesus Cristo, o justo, que intercede por nós». O mesmo título está implícito para Cristo no <span class=\"greek\">ἄλλος</span> <span class=\"greek\">παράκλητος</span> de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:16</a>. Somente o Espírito Santo é expressamente chamado <span class=\"greek\">παρ</span>. = «Auxiliador» no Quarto Evangelho: 14:16, 26; 15:26; 16:7.—HUsener, Archiv für lat. Lexikographie 2, 1885, 230ff; HSasse, Der Paraklet im J: ZNW 24, 1925, 260–77; HWindisch, Johannes u. die Synoptiker 1926, 147f, Die fünf joh. Parakletsprüche: Jülicher Festschr. 1927, 110–37; RAsting, ‘Parakleten’ i Johannes-evangeliet: Teologi og Kirkeliv. Avh. etc. ’31, 85–98; SMowinckel, D. Vorstellungen d. Spätjudentums v. Hl. Geist als Fürsprecher u. d. joh. Paraklet: ZNW 32, ’33, 97–130 (agora corroborado por 1QS 3:24f; 1QM 17:6–8); JMusger, Dicta Christi de Paracleto ’38; EPercy, Untersuchungen üb. den Ursprung d. joh. Theol. ’39; Bultmann, J ’40, 437–40; NJohansson, Parakletoi: Vorstellgen. v. Fürsprechern f. d. Menschen vor Gott in d. atl. Rel., im Spätjudent. u. Urchristent. ’40.; NSnaith, ET 57, ’45, 47–50 («Convencedor»); WHoward, Christianity acc. to St. John ’47, 71–80; WMichaelis, Con. Neot. 11, ’47, 147–62; GBornkamm, RBultmann Festschr. ’49, 12–35; CBarrett, JTS, n.s. 1, ’50, 8–15; JDavies, ibid. 4, ’53, 35–8; TPreiss, Life in Christ, ’54, 19–25; OBetz, Der Paraklet, ’63; MMiguens, El Paráclito (Juan 14–16) ’63; GJohnston, The Spirit-Paraclete in J, ’70; RBrown, The Paraclete in Modern Research, TU 102, ’68, 158–65; JVeenhof, De Parakleet ’77.—DELG s.v. <span class=\"greek\">καλέω</span>. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0270-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρακοή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρακοή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (cf. <span class=\"greek\">παρακούω</span> 2; Pla., Ep. 7, 341b; Galeno: CMG V 4, 2 p. 178, 14, Suppl. III p. 30, 2) recusa em escutar e, consequentemente, em obedecer; relutância em ouvir, desobediência (assim ApcEsdr 2:12 p. 26, 5 Tdf. [com <span class=\"greek\">παράβασις</span>]; Just.; Ps.-Clem., Hom. 2, 31; Synes., Ep. 67; Syntipas p. 97, 2; Photius, Bibl. p. 503, 5; PLond IV, 1345, 36; IV, 1393, 51 [ambos VIII d.C.]; Iren., 4, 37, 4 [Harv. II 288, 5]; Did., Gen. 90, 17; Theoph. Ant. 2, 25 p. 160, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:19</a> (cf. Just., D. 100, 4); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:6</a>; Dg 12:2. Com <span class=\"greek\">παράβασις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:2</a>.—DELG s.v. <span class=\"greek\">ἀκούω</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0270-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρακολουθέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρακολουθέω</span> futuro <span class=\"greek\">παρακολουθήσω</span>; 1.º aoristo <span class=\"greek\">παρηκολούθησα</span>; perfeito <span class=\"greek\">παρηκολούθηκα</span> (Aristoph., X., Pla.+; inscrições, papiros, 2 Macc, TestSol; JosAs 29:6; ApcMos 8; Philo, Joseph., Just.; Tat. 12, 5; Ath.) «seguir».<br><br>① Estar estreitamente associado a alguém considerado figura de autoridade, seguir, literalmente no discipulado direto: <span class=\"greek\">τοῖς</span> <span class=\"greek\">πρεσβυτέροις</span> «aos presbíteros» Papias (2, 4); <span class=\"greek\">αὐτῷ</span> «a ele»: Jesus (2, 15).—Diferentemente:<br><br>② Estar presente junto de, seguir, acompanhar, estar associado a, com dativo de pessoa (<span class=\"greek\">τύχη</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">π</span>. Demosth. 42, 21; Plut., Mor. 207e; <span class=\"greek\">πυρετοί</span> <span class=\"greek\">μοι</span> <span class=\"greek\">π</span>. Demosth. 54, 11; <span class=\"greek\">βλάβη</span> <span class=\"greek\">μοι</span> <span class=\"greek\">π</span>. PReinach 18, 15 [II a.C.]; 19, 12; PTebt 28, 2; PStras 22, 20. Cf. 2 Macc 8:11; Philo, Sacr. Abel. 70; Ath. 31, 1 [com acusativo e infinitivo]) <span class=\"greek\">σημεῖα</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">πιστεύσασιν</span> <span class=\"greek\">ταῦτα</span> <span class=\"greek\">παρακολουθήσει</span> «estes sinais acompanharão os que vieram a crer» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:17</a> (variante <span class=\"greek\">ἀκολουθήσει</span>).<br><br>③ Adequar-se à crença ou prática de alguém mediante atenção especial, seguir fielmente, seguir como regra (SIG 885, 32 <span class=\"greek\">π</span>. <span class=\"greek\">τῇ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θεῖον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πόλεως</span> <span class=\"greek\">θεραπείᾳ</span>; PTebt 124, 4 [I a.C.] <span class=\"greek\">τῇ</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">π</span>. <span class=\"greek\">πίστει</span>; 2 Macc 9:27 <span class=\"greek\">π</span>. <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐμῇ</span> <span class=\"greek\">προαιρέσει</span>) <span class=\"greek\">διδασκαλίᾳ</span> «à doutrina» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:10</a>. Esse sentido envolve apenas uma ligeira transferência da acepção «acompanhar com a mente, compreender, assimilar» (Demosth. e outros; especialmente termo técnico dos estoicos), com dativo de coisa (Polyb. 3, 32, 2; Epict. 1, 6, 13, acerca da consciência inteligente em oposição ao funcionamento meramente mecânico, a diferença entre animais e seres humanos; Vett. Val. 276, 23; SIG 718, 9 [c. 100 a.C.]; Just., D. 114, 1).<br><br>④ Prestar atenção cuidadosa a algo ao longo de um período, acompanhar alguma coisa, seguir uma sequência de acontecimentos, tomar conhecimento de, com dativo de coisa (Demosth. 18, 172 <span class=\"greek\">παρηκολουθηκότα</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">πράγμασιν</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἀρχῆς</span> = «alguém bem familiarizado com os acontecimentos desde o princípio»; 19, 257 <span class=\"greek\">ἀκριβέστατ</span>’ <span class=\"greek\">εἰδὼς</span> <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">παρηκολουθηκὼς</span> <span class=\"greek\">ἅπασι</span> <span class=\"greek\">κατηγορῶ</span> = «apresento minhas acusações como alguém que possui conhecimento exato e acompanhou tudo»; UPZ 71, 20 [152 a.C.] <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀληθείᾳ</span>; Jos., C. Ap. 1, 53, conhecimento pessoal em oposição à informação obtida de segunda mão; 218, incapacidade de compreender cabalmente certos escritos: <span class=\"greek\">μετὰ</span> <span class=\"greek\">πάσης</span> <span class=\"greek\">ἀκριβείας</span> … <span class=\"greek\">παρακολουθεῖν</span>) <span class=\"greek\">ἐμοὶ</span> <span class=\"greek\">παρηκολουθηκότι</span> <span class=\"greek\">ἄνωθεν</span> <span class=\"greek\">πᾶσιν</span> <span class=\"greek\">ἀκριβῶς</span> «a mim, que conheço bem tudo desde o princípio» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:3</a> (veja HCadbury, Beginn. II 501f; Exp. 8th ser., 144, 1922, 401–20; NTS 3, ’56/57: 128ff, «ter estado familiarizado com», e M-M.; JRopes, JTS 25, 1924, 67–71.—GWhitaker, Exp. 8th ser., 118, 1920, 262–72; 119, 1920, 380–84; 121, 1921, 239ff; BBacon, Le témoignage de Luc sur luimême: RHPR 8, 1928, 209–26. Lucas não especifica os meios pelos quais pôde afirmar seu conhecimento completo [uma tradução como «pesquisar» ou «investigar» depende da interpretação do contexto, não do conteúdo semântico de <span class=\"greek\">π</span>.]. Pode-se presumir que parte desse conhecimento procedeu dos tipos de fontes citados no v. 2. Veja ainda s.v. <span class=\"greek\">ἀνατάσσομαι</span>).—LAlexander, The Preface to Luke’s Gospel ’93, 127–31.—DELG s.v. <span class=\"greek\">ἀκόλουθος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0270-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρακούω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρακούω</span> (cf. <span class=\"greek\">παρακοή</span>) futuro <span class=\"greek\">παρακούσομαι</span>; 1.º aoristo <span class=\"greek\">παρήκουσα</span> (Aristoph., Hdt.+).<br><br>① Escutar algo sem ser pessoalmente o destinatário da fala; ouvir o que não era destinado aos próprios ouvidos, ouvir por acaso (Aristoph., Frogs 750; Pla., Euthyd. 300d), <span class=\"greek\">τὶ</span> «algo»; <span class=\"greek\">Ἰησοῦς</span> <span class=\"greek\">π</span>. <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span> «Jesus ouviu por acaso o que foi dito ao centurião» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:36</a>. Alguns comentaristas, porém, preferem o sentido 2a.<br><br>② Não prestar atenção a algo que foi ouvido.<br><br>ⓐ Ignorar, <span class=\"greek\">τὶ</span> «algo» (Plut., Philop. 378 [16, 1] <span class=\"greek\">καὶ</span> <span class=\"greek\">παριδεῖν</span> <span class=\"greek\">τι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">παρακοῦσαι</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁμαρτανομένων</span>, Mor. 522b <span class=\"greek\">ἔνια</span> <span class=\"greek\">παρακοῦσαι</span> <span class=\"greek\">κ</span>. <span class=\"greek\">παριδεῖν</span>); Jesus ignorou o que disseram (veja 1).<br><br>ⓑ Recusar-se a ouvir, desobedecer, com genitivo de pessoa ou coisa (Polyb. 24, 9, 1; Epict. 2, 15, 4 <span class=\"greek\">τῶν</span> <span class=\"greek\">λόγων</span>; Lucian, Prometh. 2; PHib 170 [247 a.C.] <span class=\"greek\">ἡμῶν</span>; Esth 3:8; TestSol 25:8 B <span class=\"greek\">μου</span>; Jos., Ant. 1, 190; 6, 141; Mel., P. 48, 343 <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:17ab</a>; STellan: Laurentianum 35, ’94, 91–134. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐντολῶν</span> «dos mandamentos» (Tob 3:4; cf. UPZ 110, 130 [164 a.C.]) 2 Cl 3:4; 6:7. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ῥήματι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:5</a> D. Sem complemento (TestDan 2:3) 2 Cl 15:5; Hv 4, 2, 6.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0270-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρακύπτω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρακύπτω</span> 1.º aoristo <span class=\"greek\">παρέκυψα</span>; infinitivo <span class=\"greek\">παρακύψαι</span> (Aristoph., Hippocr. e outros; papiros, LXX, En; JosAs 7:2 [cód. A e Pal. 364]; ApcMos 17; Philo), originalmente «inclinar-se» (para ver algo melhor; Field, Notes 80f).<br><br>① Inclinar-se com a finalidade de olhar, enfatizando a satisfação da curiosidade, dar uma olhada (Phlegon: 257 Fgm. 36, 1, 3 Jac.; POxy 475, 23 [II d.C.]; LXX) <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μνημεῖον</span> «ela se inclinou para olhar dentro do sepulcro» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:11</a> (sobre <span class=\"greek\">π</span>. <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span>, cf. Lucian, Tim. 13; Pr 7:6; Sir 21:23). <span class=\"greek\">ἐκεῖ</span> GPt 13:55. Sem complemento (Epict. 1, 1, 16; Aesop, Fab. 145 P.=251 H.; 203 Ch.; H-H. 150) <span class=\"greek\">παρακύψας</span> <span class=\"greek\">βλέπει</span> «inclinando-se, vê» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:5</a>. Cf. GPt 13:56.<br><br>② Procurar descobrir algo intelectualmente, olhar para dentro de, examinar, extensão figurada de 1; <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span> «para dentro de algo» (Philo, Leg. ad Gai. 56); <span class=\"greek\">εἰς</span> <span class=\"greek\">νόμον</span> <span class=\"greek\">τέλειον</span> «para a lei perfeita» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:25</a> (aqui a expressão é sugerida pela imagem de alguém que se contempla num espelho, vv. 23f). Sobre os anjos (cf. En 9:1), que procuram <span class=\"greek\">παρακύπτειν</span> no evangelho do Cristo sofredor e glorificado, duas possibilidades: obter uma visão clara, ou lançar-lhe uma olhada furtiva (assim POxy, veja 1 acima; cf. Demosth. 4, 24) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:12</a>.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0270-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραλαμβάνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραλαμβάνω</span> (Eur., Hdt.+), 2.º aoristo <span class=\"greek\">παρέλαβον</span>, 1.ª pessoa plural <span class=\"greek\">παρελάβαμεν</span> (AcPlCor 1:5), 3.ª pessoa plural <span class=\"greek\">παρελάβοσαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:6</a>, variante (B-D-F §84, 2; 14; Mlt-H. 209); infinitivo do 1.º aoristo <span class=\"greek\">παραλάβαι</span> (GJs 9:1); infinitivo perfeito <span class=\"greek\">παρειληφέναι</span> Papias (2, 2); futuro médio <span class=\"greek\">παραλήμψομαι</span> (sobre a grafia com <span class=\"greek\">μ</span>, veja Mayser p. 194f; Thackeray p. 108ff; B-D-F §101 p. 53; §Mlt-H. 246f; Reinhold 46f; WSchulze, Orthographica 1894.—Sobre a voz média, veja B-D-F §77; Rob. 356). Passivo: 1.º futuro <span class=\"greek\">παραλημφθήσομαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:34f</a> (sobre a grafia com <span class=\"greek\">μ</span>, veja acima, sob futuro médio); particípio do 1.º aoristo acusativo feminino singular <span class=\"greek\">παραλημφθεῖσαν</span> Wsd 16:14; perfeito <span class=\"greek\">παρείλημμαι</span> Num 23:20.<br><br>① Tomar para associação íntima, tomar (para si), levar consigo, trazer junto (Gen 47:2; 2 Macc 5:5; TestAbr A 15 p. 95, 8f [Stone p. 38]; Jos., Vi. 66) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:13f</a>, 20f; 17:1; 26:37; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:36</a>; 5:40; 9:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.39\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:39</a>; 16:33; 21:24, 26, 32 (variante <span class=\"greek\">λαβών</span>); 23:18; Ox 840, 7; Hs 6, 3, 3. <span class=\"greek\">παραλαμβάνει</span> <span class=\"greek\">ἕτερα</span> <span class=\"greek\">πνεύματα</span> <span class=\"greek\">ἑπτά</span> «(o espírito maligno) traz consigo outros sete espíritos (para ajudá-lo)» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:26</a> (Menand., Col. 123 S. [112 Kö.] <span class=\"greek\">ἑξήκονθ</span>’ <span class=\"greek\">ἑταίρους</span> <span class=\"greek\">παραλαβών</span>). Passivo (Diod S 2, 40, 2): <span class=\"greek\">εἷς</span> <span class=\"greek\">παραλαμβάνεται</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">εἷς</span> <span class=\"greek\">ἀφίεται</span> «um é levado (pelos anjos, veja <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:31</a>), o outro é deixado» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:40</a>; cf. v. 41; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:34f</a>. <span class=\"greek\">π</span>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">μεθ</span>’ <span class=\"greek\">ἑαυτοῦ</span> (<span class=\"greek\">μετὰ</span> <span class=\"greek\">σοῦ</span>, <span class=\"greek\">μετ</span>’ <span class=\"greek\">αὐτοῦ</span>; cf. Gen 22:3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:45</a>; 18:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:33</a>. Com acusativo de pessoa e destino indicado por <span class=\"greek\">εἰς</span>, «levar (consigo) para, a» (Aelian, VH 2, 18; Num 23:27; Just., D. 99, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:5</a>, 8; 27:27. <span class=\"greek\">παραλήμψομαι</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἐμαυτόν</span> «eu vos tomarei para mim» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:3</a> (veja Dssm., LO 144 [LAE 166]; «comigo para minha casa», AHumphries, ET 53, ’41/42, 356). <span class=\"greek\">π</span>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἰδίαν</span> «levar alguém à parte» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:17</a>. Também sem <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἰδίαν</span>, com a mesma finalidade de instrução particular, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:10</a> (aqui <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἰδίαν</span> não se liga gramaticalmente a <span class=\"greek\">παραλ</span>.); 18:31.—Sobre a esposa: «recebê-la em casa» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:20</a>, 24 (cf. Hdt. 4, 155; Lucian, Toxar. 24; SSol 8:2; Jos., Ant 1, 302; 17, 9). José leva Maria do templo para sua própria casa GJs 9:1, 3; 13:1; 15:2; 16:1, 3.—«Tomar sob custódia, prender» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.35\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:35</a> D. Passivo GPt 1:2 <span class=\"greek\">παρ</span>[<span class=\"greek\">αλη</span>]<span class=\"greek\">μφθῆναι</span> (outra restituição possível: <span class=\"greek\">παρ</span>[<span class=\"greek\">απε</span>]<span class=\"greek\">μφθῆναι</span>, veja aparato e <span class=\"greek\">παραπέμπω</span>).<br><br>② Obter domínio sobre algo ou receber jurisdição, assumir, receber.<br><br>ⓐ <span class=\"greek\">τινά</span>, «alguém», um prisioneiro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:16b</a> (cf. <span class=\"greek\">παρέδωκεν</span>, ibid., v. 16a.—Ambos os verbos nesse sentido em Appian, Bell. Civ. 6, 76 §310f).<br><br>ⓑ <span class=\"greek\">τὶ</span>, «alguma coisa».<br><br><span class=\"greek\">α</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">διακονίαν</span> «o ministério» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:17</a> (SIG 663, 12 [c. 200 a.C.], o ofício sacerdotal); <span class=\"greek\">τὶ</span> <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> Hs 6, 2, 6.<br><br><span class=\"greek\">β</span>. <span class=\"greek\">βασιλείαν</span> <span class=\"greek\">ἀσάλευτον</span> «receber um reino que não pode ser abalado» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.28\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:28</a> (<span class=\"greek\">βας</span>. <span class=\"greek\">π</span>.: Hdt. 2, 120; OGI 54, 5ff [III a.C.]; 56, 6; 90, 1; 8; 47; 2 Macc 10:11; Da 6:1, 29; Jos., Ant. 15, 16, C. Ap. 1, 145; Just., D. 32, 1. Sobre os <span class=\"greek\">ἅγιοι</span> <span class=\"greek\">ὑψίστου</span>, Da 7:18).<br><br><span class=\"greek\">γ</span>. Sobre uma herança intelectual ou espiritual (Hdt., Isocr., Pla. e outros, especialmente mistérios e cerimônias recebidos por tradição [veja <span class=\"greek\">παραδίδωμι</span> 3]: Theon Smyrn., Expos. Rer. Math. p. 14 Hiller <span class=\"greek\">τελετὰς</span> <span class=\"greek\">παραλ</span>.; cf. Plut., Demetr. 900 [26, 1]; Porphyr., Abst. 4, 16; Herm. Wr. 1, 26b; CIA III 173; também o termo rabínico <span class=\"hebrew\" dir=\"rtl\">קִבֵּל</span>) <span class=\"greek\">τὶ</span>, «algo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:3</a> (com <span class=\"greek\">παραδίδωμι</span>, como Jos., Ant. 19, 31); B 19:11; D 4:13. <span class=\"greek\">παρελάβετε</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span> «recebestes a proclamação ou ensinamento» AcPl Ha 8, 25 = Ox 1602, 38 e BMM recto 32 (sobre variantes da tradição textual, veja a nota de Sander p. 85). <span class=\"greek\">παρ</span>’ <span class=\"greek\">ὸ̔</span> <span class=\"greek\">παρελάβετε</span> (=<span class=\"greek\">παρὰ</span> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">ὅ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:9</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">νόμιμα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> Hv 1, 3, 4. <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἅγιον</span> Hs 9, 25, 2. <span class=\"greek\">ἃ</span> <span class=\"greek\">παρέλαβον</span> <span class=\"greek\">κρατεῖν</span> «coisas que lhes foram transmitidas para guardar» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:4</a> (veja B-D-F §390, 3). <span class=\"greek\">τὶ</span> <span class=\"greek\">παρά</span> <span class=\"greek\">τινος</span> (Pla., Lach. 197d, Euthyd. 304c <span class=\"greek\">σοφίαν</span> <span class=\"greek\">παρά</span> <span class=\"greek\">τινος</span>; a construção com <span class=\"greek\">παρά</span> é comum em inscrições e papiros; cf. Philo, Cher. 68) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:6</a> (<span class=\"greek\">παράδοσιν</span> <span class=\"greek\">παραλ</span>.); AcPlCor 1:5. <span class=\"greek\">παρελάβετε</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πῶς</span> <span class=\"greek\">δεῖ</span> <span class=\"greek\">περιπατεῖν</span> «aprendestes de nós como deveis proceder» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:1</a>. <span class=\"greek\">παρὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐκείνοις</span> <span class=\"greek\">γνωρίμων</span> Papias (2, 2). <span class=\"greek\">ὡς</span> <span class=\"greek\">παρέλαβεν</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἁγίου</span> EpilMosq 2 (com <span class=\"greek\">παραδίδωμι</span>). <span class=\"greek\">παρέλαβον</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span>, <span class=\"greek\">ὸ̔</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">παρέδωκα</span> <span class=\"greek\">ὑμῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:23</a> (veja <span class=\"greek\">ἀπό</span> 5d). <span class=\"greek\">ἀπὸ</span> (<span class=\"greek\">ὑπὸ</span>) <span class=\"greek\">τῶν</span> <span class=\"greek\">θυγατέρων</span> <span class=\"greek\">Φιλίππου</span> Papias (11:2; cf. 2:9). <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πρὸ</span> <span class=\"greek\">ἐμοῦ</span> <span class=\"greek\">ἀποστόλων</span> AcPlCor 2:4 (com <span class=\"greek\">παραδίδωμι</span>).—<span class=\"greek\">παραλ</span>. <span class=\"greek\">τὸν</span> <span class=\"greek\">Χριστὸν</span> <span class=\"greek\">Ἰης</span>. «aceitar Cristo Jesus», isto é, a proclamação dele como Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:6</a>.<br><br>③ Por vezes a ênfase recai menos no recebimento ou na transmissão e mais no fato de que o verbo implica concordância ou aprovação, aceitar.<br><br>ⓐ Com referência a pessoas: <span class=\"greek\">οἱ</span> <span class=\"greek\">ἴδιοι</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">παρέλαβον</span> «os seus não o aceitaram» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:11</a>.<br><br>ⓑ Com referência a ensinamento e pregação (Just., A I, 13, 1 <span class=\"greek\">μόνην</span> <span class=\"greek\">ἀξίαν</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">τιμὴν</span> <span class=\"greek\">ταύτην</span> <span class=\"greek\">παραλαβόντες</span>), «aceitar»: <span class=\"greek\">τὸ</span> <span class=\"greek\">εὐαγγέλιον</span> <span class=\"greek\">ὸ̔</span> <span class=\"greek\">εὐηγγελισάμην</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">ὸ̔</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">παρελάβετε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:1</a>. <span class=\"greek\">ἃ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐμάθετε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">παρελάβετε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:9</a>.—M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0270-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραλέγομαι</h1><div class=\"entry-meta\"><span>verbo médio depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραλέγομαι</span> (cf. <span class=\"greek\">λέγομαι</span> no sentido «escolher, selecionar»; latim lego como termo náutico, Vergil, Georgics 2, 44; semelhante ao inglês pick, OED, verbo IV, 7, b), navegar ao longo da costa (Strabo 13, 1, 22), com acusativo do lugar por que se passa (Hanno [IV a.C.], Periplus 11: CMüller, GGM I [1855] p. 9 = linha 57 Oik., veja também apêndice p. 35, 11; Diod S 13, 3, 3 <span class=\"greek\">τὴν</span> <span class=\"greek\">Ἰταλίαν</span>; 14, 55, 2), <span class=\"greek\">αὐτήν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:8</a>; <span class=\"greek\">τὴν</span> <span class=\"greek\">Κρήτην</span> v. 13.—Field, Notes 144. DELG s.v. <span class=\"greek\">λέγω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0270-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραλείπω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραλείπω</span> 2.º aoristo <span class=\"greek\">παρέλιπον</span>; perfeito <span class=\"greek\">παραλέλοιπα</span>. Passivo: particípio aoristo genitivo plural <span class=\"greek\">παραλειφθέντων</span> (Just., D. 14, 3). Do sentido «deixar de lado, negligenciar» (Eur., Thu.+) passa-se facilmente a «deixar de fora, omitir», especialmente com referência à fala ou à escrita (Eur., Hel. 773; 976; Thu. 2, 51, 1; Pla., Meno 97b; Strabo 1, 1, 23; Plut., Mor. 114b; Just., A I, 61, 1 e outros), <span class=\"greek\">τὶ</span>, «algo» (Diod S 3, 66, 5; Jos., Ant. 1, 17, Vi. 261) B 17:1; Papias (2:15).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0270-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραλημφθήσομαι</h1><div class=\"entry-meta\"><span>remissão verbal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραλημφθήσομαι</span>: veja <span class=\"greek\">παραλαμβάνω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0270-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παράλιος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παράλιος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">ἅλς</span> «mar»; Aeschyl. e outros; inscrições, LXX; Philo, Agr. 81; Joseph.—Também com três terminações: SibOr 3, 493), relativo a estar situado junto ao mar; como substantivo <span class=\"greek\">ἡ</span> <span class=\"greek\">παράλιος</span>, subentendido <span class=\"greek\">χώρα</span> (Jos., C. Ap. 1, 60), «litoral, região costeira» (Polyb. 3, 39, 3; Diod S 3, 15, 41; Arrian, Anab. 1, 24, 3; 2, 1, 1; Dt 33:19; Jos., Bell. 1, 409; TestZeb 5:5 com variante.—<span class=\"greek\">ἡ</span> <span class=\"greek\">παραλία</span> já ocorre em Hdt. 7, 185 e predomina em Polyb.; Diod S 20, 47, 2; Arrian, Anab. 3, 22, 4; 6, 15, 4; LXX; Jos., Ant. 12, 292). <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">παραλίου</span> <span class=\"greek\">Τύρου</span> <span class=\"greek\">καί</span> <span class=\"greek\">Σιδῶνος</span> «da região costeira de Tiro e Sidom» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:17</a> (cf. Diod S 11, 14, 5 <span class=\"greek\">ἡ</span> <span class=\"greek\">παράλιος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Ἀττικῆς</span>; Jos., C. Ap. 1, 61 <span class=\"greek\">ἡ</span> <span class=\"greek\">παράλιος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Φοινίκης</span>).—B. 32. DELG s.v. <span class=\"greek\">ἅλς</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0270-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραλλαγή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραλλαγή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">παραλλάσσω</span>; Aeschyl., Pla. e outros; 4 Km 9:20; EpArist 75. Raramente como termo técnico de astronomia [Cat. Cod. Astr. VIII/3, 113]), «mudança, variação» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:17</a> (cf. TestJob 33:5 <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> … <span class=\"greek\">αἰῶν</span> … <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀπαραλλάκτου</span>).—DELG s.v. <span class=\"greek\">ἄλλος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0270-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραλλάσσω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραλλάσσω</span>, imperativo aoristo 2.ª pessoa singular <span class=\"greek\">παράλλαξον</span> e infinitivo <span class=\"greek\">παραλλάξαι</span> LXX; particípio perfeito passivo <span class=\"greek\">παρηλλαγμένος</span> (trágicos, Hdt. e outros; PHib 27, 50 [III a.C.]; Sb 4947, 4; LXX), «mudar», enfatizando a diferença; «modificar». <span class=\"greek\">παρηλλαγμένος</span> «estranho, extraordinário, peculiar» (Polyb. 2, 29, 1; 3, 55, 1; Diod S 14, 70, 4; 17, 90, 1; Plut., Thes. 16 [34, 3], Them. 124 [24, 3]; Lucian, Dial. Deor. 10, 2; TestSol 1:3 L; Philo, Poster. Cai. 9). <span class=\"greek\">διάλεκτος</span> <span class=\"greek\">παρηλλαγμένη</span> «uma língua peculiar» Dg 5:2.—M-M. s.v. <span class=\"greek\">παραλλαγή</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0270-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραλογίζομαι</h1><div class=\"entry-meta\"><span>verbo médio depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραλογίζομαι</span>, médio depoente; 1.º aoristo <span class=\"greek\">παρελογισάμην</span> (Isocr., Demosth. e outros; inscrições, papiros, LXX; PsSol 4:11).<br><br>① Com acusativo de pessoa (Aeschin. e outros; Epict. 2, 20, 7; Dio Chrys. 10 [11], 108; PMagd 29, 5 [III a.C.]; PAmh 35, 12; LXX; Jos., Ant. 11, 275), «enganar, iludir» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:4</a>; IMg 3:2. <span class=\"greek\">ἑαυτόν</span> «enganar-se a si mesmo» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:22</a>.<br><br>② Com acusativo de coisa, «calcular fraudulentamente, defraudar», talvez «distorcer» (OGI 665, 15 <span class=\"greek\">δαπάνας</span> … <span class=\"greek\">παραλογις</span>[<span class=\"greek\">θεί</span>]<span class=\"greek\">σας</span>, acerca de despesas contabilizadas fraudulentamente; Gen 31:41 <span class=\"greek\">τὸν</span> <span class=\"greek\">μισθόν</span>) <span class=\"greek\">τὰς</span> <span class=\"greek\">ἐντολὰς</span> <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">Χριστοῦ</span> 2 Cl 17:6.—DELG s.v. <span class=\"greek\">λέγω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0270-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραλόγως</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραλόγως</span>, advérbio de <span class=\"greek\">παράλογος</span> (Thu., Aristot. e outros; OGI 665, 33; TestAbr A 19 p. 102, 21 [Stone p. 52]; Jos., Bell. 4, 49), «de maneira irracional» (Polyb. 1, 74, 14; Celsus 5, 14; TestAbr A 20 p. 102, 21 [Stone p. 52]; Ath., R. 11 p. 59, 15) Dg 11:1.—DELG s.v. <span class=\"greek\">λέγω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0270-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραλυτικός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo substantivado</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραλυτικός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">παραλύω</span>; Diosc. 1, 16; Vett. Val. 110, 34; 127, 21; Hippiatr. I 433, 6; Papiri letterari greci, ed. ACarlini et al. ’78, nº 32, 17: New Docs 3, 79; Just., A I, 22, 6), «paralítico», empregado apenas como substantivo (<span class=\"greek\">ὁ</span>) <span class=\"greek\">π</span>., «pessoa paralítica, paralítico» (Rufus [II d.C.] em Oribas. 8, 39, 8; Geopon. 8, 11) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:24</a>; 8:6; 9:2ab, 6 (sobre Mt 8 e 9, veja JKingsbury, CBQ 40, ’79, 559–73); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:3</a>–5, 9f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:24</a>, variante; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:3</a> D; AcPl [Ha 8, 37] //BMM verso, 11 <span class=\"greek\">παρ</span>[<span class=\"greek\">αλυτι</span>]<span class=\"greek\">κοὺς</span> <span class=\"greek\">ἐγ</span>[<span class=\"greek\">είρων</span>].—PSchmidt, Die Geschichte Jesu II 1904, 205ff; 261.—DELG s.v. <span class=\"greek\">λύω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0270-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παράλυτος, ον</h1><div class=\"entry-meta\"><span>adjetivo substantivado</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παράλυτος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">παραλύω</span>), «paralítico» (Artem. 4, 67 p. 244, 2), empregado apenas como substantivo <span class=\"greek\">ὁ</span> <span class=\"greek\">π</span>. «o paralítico» (Artem. 4, 67 p. 244, 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:9</a> D; AcPl [Ha 8f] //BMM verso 40 (=PMich 3788 verso 9; <span class=\"greek\">παραλύτους</span> em vez de <span class=\"greek\">παραλυτικούς</span>).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0270-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραλύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραλύω</span> (Eur., Hdt.+), futuro 3.ª pessoa singular <span class=\"greek\">παραλύσει</span> Gen 4:15; aoristo 3.ª pessoa singular <span class=\"greek\">παρέλυσε</span> LXX. Passivo: futuro 3.ª pessoa plural <span class=\"greek\">παραλυθήσονται</span>; aoristo 3.ª pessoa singular e plural <span class=\"greek\">παρελύθη</span>, -<span class=\"greek\">θησαν</span> LXX; particípio perfeito <span class=\"greek\">παραλελυμένος</span>, «tornar fraco, desfazer, enfraquecer, incapacitar» (Hdt. e outros.—Diod S 20, 72, 2 <span class=\"greek\">παραλελυμένος</span> por causa da velhice); em linguagem figurada <span class=\"greek\">τὰ</span> <span class=\"greek\">παραλελυμένα</span> <span class=\"greek\">γόνατα</span> «os joelhos enfraquecidos» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:12</a> (Is 35:3; Sir 25:23; cf. PsSol 8:5.—Diod S 18, 31, 4 <span class=\"greek\">παραλελυμένος</span>, de um homem aleijado por um golpe atrás do joelho). <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">παραλελυμένος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:33</a> (Artem. 5, 51 <span class=\"greek\">ἐνόσησε</span> <span class=\"greek\">κ</span>. <span class=\"greek\">παρελύθη</span>; 1, 50 p. 48, 11). Substantivado, <span class=\"greek\">ὁ</span> <span class=\"greek\">παραλελυμένος</span>, «o paralítico» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:24</a> (variante <span class=\"greek\">τῷ</span> <span class=\"greek\">παραλυτικῷ</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:7</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0270-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραμένω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραμένω</span>, futuro <span class=\"greek\">παραμενῶ</span>; 1.º aoristo <span class=\"greek\">παρέμεινα</span>, imperativo <span class=\"greek\">παράμεινον</span> (Hom.+), originalmente «permanecer, ficar» (ao lado de alguém).<br><br>① Permanecer numa condição ou situação, permanecer, continuar.<br><br>ⓐ Uso absoluto: <span class=\"greek\">εὔχομαι</span> <span class=\"greek\">παραμεῖναι</span> <span class=\"greek\">αὐτόν</span> «desejo que ele continue» IEph 2:1 (veja FPreisigke, Griech. Urkunden d. ägypt. Mus. in Kairo 1911 nº 15, 9).<br><br>ⓑ Com dativo de pessoa, «ficar ou permanecer com alguém» (Hom. e outros; SIG 1209, 24f; 1210, 7f; PPetr III, 2, 21 [III a.C.]; PTebt 384, 21; 32; POxy 725, 43f; Gen 44:33). <span class=\"greek\">μενῶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">παραμενῶ</span> <span class=\"greek\">πᾶσιν</span> <span class=\"greek\">ὑμῖν</span> «permanecerei e continuarei com todos vós» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:25</a>; AcPl Ha 6, 35 (<span class=\"greek\">παραμ</span>. tem o sentido «continuar vivo, continuar vivendo», Hdt. 1, 30; Dio Chrys. 3, 124; Artem. 2, 27; 67. Quanto à conotação de «servir» em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:25</a>, veja 2 abaixo). <span class=\"greek\">παρέμειναν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πνεύματα</span> <span class=\"greek\">αὐτοῖς</span> «os espíritos permaneceram com eles» Hs 9, 15, 6.—Com preposição: <span class=\"greek\">παραμ</span>. <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> «ficar com alguém» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:6</a> (variante <span class=\"greek\">καταμ</span>.); <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span> Ox 404 (Hs 10, 3, 2, veja Whittaker p. 109) recto [<span class=\"greek\">μετὰ</span> <span class=\"greek\">σοῦ</span> <span class=\"greek\">παρα</span>]<span class=\"greek\">μ̣ένουσι̣</span>[<span class=\"greek\">ν</span> (cf. <span class=\"greek\">σὺν</span> <span class=\"greek\">Τρύφωνι</span> <span class=\"greek\">παραμεινάντων</span> Just., D. 56, 13). <span class=\"greek\">παραμ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">ζωὴν</span> <span class=\"greek\">αἰώνιον</span> «perdurar até a vida eterna» Hv 2, 3, 2.<br><br>② Continuar no exercício de uma função oficial, permanecer numa ocupação ou cargo (Diod S 2, 29, 5), uso absoluto, acerca dos sacerdotes no santuário terreno, impedidos pela morte de continuar no ofício, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.23\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:23</a> (cf. Jos., Ant. 9, 273; cf. New Docs 4, 98). Daquele que se interessa pela lei perfeita, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:25</a> (talvez com a conotação de «servir»; veja Vitelli sobre PFlor 44, 19 e M-M.).—Continuar num estado ou qualidade: <span class=\"greek\">παραμένουσα</span> <span class=\"greek\">πραεῖα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἡσύχιος</span> «ela permanece mansa e tranquila» Hm 5, 2, 3. <span class=\"greek\">παράμεινον</span> <span class=\"greek\">ταπεινοφρονῶν</span> «continua humilde» Hs 7:6.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0270-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παράμονος ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παράμονος</span> <span class=\"greek\">ον</span> (<span class=\"greek\">παραμένω</span>; forma rara de <span class=\"greek\">παραμόνιμος</span>, «constante, firme»; Pind. e outros).<br><br>① Relativo a uma qualidade duradoura, «durável, constante, persistente», acerca de coisas ou circunstâncias (Plut., Mor. 114f <span class=\"greek\">πένθος</span>; Vett. Val. p. 292, 30; Geopon. 1, 12, 5) <span class=\"greek\">δόξα</span> (com <span class=\"greek\">ἄτρεπτος</span>) IEph ins; (com <span class=\"greek\">αἰώνιος</span>) <span class=\"greek\">χαρά</span> IPhld ins; <span class=\"greek\">ἀφροσύνη</span> Hs 6, 5, 2.<br><br>② Acerca de pessoas (Hesych. = <span class=\"greek\">καρτερός</span>), originalmente relativo à constância de caráter, «firme, constante»; em nossa literatura com sentido desfavorável, «obstinado, persistente» Hs 5, 5, 1. Com dativo daquilo em que alguém persiste: <span class=\"greek\">παράμονοι</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">καταλαλιαῖς</span> <span class=\"greek\">αὐτῶν</span> «caluniadores obstinados» 9, 23, 3.—DELG s.v. <span class=\"greek\">μένω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0270-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραμυθέομαι</h1><div class=\"entry-meta\"><span>verbo médio depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραμυθέομαι</span>, médio depoente (Hom. e outros; inscrições, papiros; TestJob; TestAsh 6:6 [veja aparato de Denis]; ParJer 7:26; 2 Macc 15:9; Jos., Bell. 1, 627, Ant. 6, 38; Ath., R. 12 p. 61, 19), «consolar, animar», <span class=\"greek\">τινά</span> «alguém» (Thu. 2, 44, 1 e outros) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:12</a> (JChapa, NTS 40, ’94, 150–60). <span class=\"greek\">τοὺς</span> <span class=\"greek\">ὀλιγοψύχους</span> «os desanimados» 5:14 (Arrian, Anab. 4, 9, 7, consolação dirigida a Alexandre quando estava deprimido).—Especialmente em relação com a morte ou outros acontecimentos trágicos, «consolar, confortar», com acusativo de pessoa (Thu. 2, 44, 1 e outros; Plut., Mor. 104c; SIG 796b, 13; 39f; 889, 20; IG V/2 nº 517, 13.—KBuresch, Consolationum a Graecis Romanisque scriptarum historia critica: Leipz. Studien z. klass. Phil. 9, 1886; FDanker, Threnetic Penetration in Aeschylus and Sophocles, diss. Chicago, ’63) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.31\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:31</a>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> «consolar alguém a respeito de alguém» v. 19.—PJoüon, RSR 28, ’38, 311–14. CClassen, WienerStud 107/8, ’94/95, 327f, observa o emprego retórico de <span class=\"greek\">π</span>. e sua ligação com <span class=\"greek\">παρακαλεῖν</span> em diversas passagens.—M-M. TW. Spicq. Sv.</p></section></article>"};
